.rs-symptom-diary-time{font-size:0.75rem;color:var(--text-secondary);font-variant-numeric:tabular-nums}
.rs-symptom-diary-content{display:grid;gap:0.5rem;min-width:0}
.rs-symptom-diary-head{display:flex;justify-content:space-between;flex-wrap:wrap;align-items:baseline;gap:0.25rem 1rem}
.rs-symptom-diary-symptom{margin:0;font-size:0.875rem;font-weight:600}
.rs-symptom-diary-intensity{margin:0;font-size:0.75rem;color:var(--text-secondary)}
.rs-symptom-diary-body{margin:0;max-width:66ch;font-size:0.875rem}
.rs-symptom-diary-summary{min-height:var(--hit);min-width:var(--hit);display:list-item;align-content:center;cursor:pointer;font-size:0.875rem;border-radius:var(--radius-sm);outline:none;outline-offset:2px;padding-inline:0.25rem}
.rs-symptom-diary-summary:focus-visible{outline:2px solid var(--text)}
.rs-symptom-diary-actions{display:flex;flex-wrap:wrap;gap:0.5rem}

